#!/usr/bin/env python3
# THE NUMBERS WALK, sitting 14 — THE BORDERS (2026-09-12): the store's glosses at the chapter's seats read back into the display layer's override
# file — BY REFERENCE for the chapter's own seats (31 rows) and BY GLOSS where the store's every token of the gloss is the one word (the census in
# bor_ink.py: the border-word's six gloss forms, the salt, the north, Dan, Nun, the wilderness, eastward, the sunrise, beyond, the goings-out, the
# lot, the sea, the Jordan, the borders, barnea, and the broken "inherit--mode-of-descent)" family — 28 rows). Display only; the frozen unit
# untouched. The rows are the same literals bor_ink.py asserts present. Run ONCE (the anchors assert the rows absent first).
import re
P = '<repo-old>/logic/glosses/word_gloss_overrides.yaml'
t = open(P, encoding='utf-8').read()
assert '"Num.34.' not in t and '"cord": "border"' not in t
REF = [('Num.34.3:2', 'the-side-of', "pe'at — the tabernacle's side-word (Exod 27:9), not a mouth"), ('Num.34.3:7', 'alongside', "'on the hands of Edom' — Onkelos 'on the borders of'"), ('Num.34.3:13', 'from-the-end-of', ''), ('Num.34.3:14', 'the-sea-of', 'the Salt Sea'), ('Num.34.4:0', 'and-shall-turn', 'the border-turning verb (Joshua 15-19)'), ('Num.34.4:4', 'to-the-ascent-of', ''), ('Num.34.4:5', 'Akrabbim', 'the gloss had carried the whole compound'), ('Num.34.4:7', 'to-Zin', ''), ('Num.34.4:12', 'to-Kadesh-', ''), ('Num.34.4:14', 'and-shall-go-out', 'the border goes out, nothing is brought forth'), ('Num.34.4:15', 'Hazar-', ''), ('Num.34.4:16', 'addar', ''), ('Num.34.4:18', 'to-Azmon', ''), ('Num.34.5:0', 'and-shall-turn', ''), ('Num.34.5:3', 'the-brook-of', "nachlah — the brook with the directional ending, not 'stream-suffix'"), ('Num.34.5:7', 'to-the-sea', ''), ('Num.34.6:1', 'the-west', 'the sea as the direction'), ('Num.34.6:11', 'the-west', ''), ('Num.34.8:3', 'Lebo-', 'the name Lebo-hamath, not the verb come'), ('Num.34.8:6', 'the-goings-out-of', ''), ('Num.34.8:8', 'to-Zedad', ''), ('Num.34.9:0', 'and-shall-go-out', ''), ('Num.34.9:2', 'to-Ziphron', ''), ('Num.34.9:5', 'Hazar-', ''), ('Num.34.10:4', 'from-Hazar-', ''), ('Num.34.10:6', 'to-Shepham', ''), ('Num.34.11:8', 'and-shall-reach', "the blotting verb's consonants on the border — Onkelos 'and it shall reach'"), ('Num.34.11:11', 'the-sea-of', 'the sea of Chinnereth'), ('Num.34.12:5', 'the-sea-of', ''), ('Num.34.12:12', 'round-about', ''), ('Num.34.13:15', 'to-give', '')]
GL = [('cord', 'border', "the border-word at every seat of the gloss (19 tokens censused at sitting 14)"), ('the-cord', 'the-border', ''), ('and-cord', 'and-the-border', ''), ('to-cord', 'to-the-border', ''), ('from-cord', 'from-the-border', ''), ('in-cord', 'in-the-border-of', ''), ('the-powder', 'the-salt', 'the Salt Sea at all four seats'), ('hidden', 'north', 'the direction at all eight seats'), ('Daniel', 'Dan', 'the tribe and its father at all twenty-five seats'), ('Non', 'Nun', "Joshua's father at all sixteen"), ('from-pasture', 'from-the-wilderness-of', ''), ('front-suffix', 'eastward', ''), ('sunrise-suffix', 'toward-the-sunrise', ''), ('from-region-across', 'from-beyond', ''), ('exit-him/its', 'its-goings-out', "the border's outlet-word, the Torah's five seats all in Numbers 34"), ('in-pebble', 'by-lot', 'all four seats the lot of the land (26:55, 33:54, 34:13, 36:2)'), ('the-seas', 'the-sea', 'singular at all thirty-five'), ('the-Jordan-suffix', 'to-the-Jordan', ''), ('to-boundary-her/its', 'by-its-borders', ''), ('Kadeshbarnea', 'barnea', 'the second half of the name; the first half is the previous token'), ('inherit--mode-of-descent)', 'inherit', 'the broken gloss with its stray parenthesis — the whole family below'), ('to-inherit--mode-of-descent)', 'to-apportion', ''), ('and-inherit--mode-of-descent)', 'and-inherit', ''), ('and-inherit--mode-of-descent)-us/our', 'and-take-us-as-inheritance', ''), ('in-inherit--mode-of-descent)', 'when-he-apportioned', ''), ('inherit--mode-of-descent)-her/its', 'cause-to-inherit-it', ''), ('inherit--mode-of-descent)-him/its', 'causes-to-inherit', ''), ('inherit--mode-of-descent)-you/your', 'gives-you-to-inherit', '')]
A1 = '  "and-trample": "and-wash"                 # the washing of garments at twenty Torah seats\n'
assert t.count(A1) == 1
gl_block = A1 + '\n  # THE NUMBERS WALK sitting 14 (2026-09-12, Numbers 34): the store\'s glosses whose every token is the one word (censused in the reading\'s ink script) — RESEARCH_LOG.md\n' + ''.join(f'  "{k}": "{v}"' + (f'   # {n}' if n else '') + '\n' for k, v, n in GL)
t = t.replace(A1, gl_block)
A2 = '  "Num.33.49:6": "Abel-"\n'
assert t.count(A2) == 1
ref_block = A2 + '  # THE NUMBERS WALK sitting 14 (2026-09-12, Numbers 34): the store\'s glosses at the chapter\'s seats, by reference — RESEARCH_LOG.md\n' + ''.join(f'  "{k}": "{v}"' + (f'   # {n}' if n else '') + '\n' for k, v, n in REF)
t = t.replace(A2, ref_block)
open(P, 'w', encoding='utf-8').write(t)
import yaml
d = yaml.safe_load(open(P, encoding='utf-8'))
assert all(d['by_ref'][k] == v for k, v, _ in REF) and all(d['by_gloss'][k] == v for k, v, _ in GL)
print('override rows written: by_ref', len(REF), 'by_gloss', len(GL), '| by_ref total', len(d['by_ref']), '| by_gloss total', len(d['by_gloss']))
